#include <iostream>
int main(){int n;std::cout<<"Enter array size (1-100): ";if(!(std::cin>>n)||n<1||n>100){std::cout<<"Array size must be from 1 to 100.\n";return 0;}int largest=0,second=0;bool hasLargest=false,hasSecond=false;for(int i=0;i<n;++i){int v;if(!(std::cin>>v)){std::cout<<"Enter exactly "<<n<<" whole numbers.\n";return 0;}if(!hasLargest||v>largest){if(hasLargest){second=largest;hasSecond=true;}largest=v;hasLargest=true;}else if(v<largest&&(!hasSecond||v>second)){second=v;hasSecond=true;}}if(std::cin>>std::ws&&std::cin.peek()!=std::char_traits<char>::eof()){std::cout<<"Enter only the array values.\n";return 0;}if(hasSecond)std::cout<<"Second largest distinct value: "<<second<<'\n';else std::cout<<"No distinct second largest value.\n";}
